简单封装引入：
use PhpOffice\PhpWord\TemplateProcessor;use PhpOffice\PhpWord\IOFactory;

封装方法：
/**    * word文档变量替换     * @param string  $tmpurl  模板word路径    * @param array   $search  搜索文档中的变量名  一维数组：[&#x27;param1&#x27;,&#x27;param1&#x27;]    * @param array   $replace 需替换变量名的值  一维数组：[&#x27;value1&#x27;,&#x27;value1&#x27;]    * $param string  $alias 别名    * $param string  $pic_replcae 图片替换（如个人照，公章等）    * @param int     $type  类型 0-模板替换生成新文档 1-获取文档追加更新    */public status function replaceWord($tmpurl = &#x27;&#x27;, $search = [], $replace = [] , $type = 0, $alias = &#x27;&#x27;,$pic_replcae = [])&#123;    try &#123;        if(!$tmpurl) return [&#x27;code&#x27;=&gt;500,&#x27;msg&#x27;=&gt;&#x27;模板文件为空&#x27;];        //模板work文档，替换成绝对路径        $tmpUrl = str_replace(request()-&gt;domain().&#x27;/&#x27;,env(&quot;root_path&quot;),$tmpurl);        $tp = new TemplateProcessor($tmpUrl);        //替换变量        $tp-&gt;setValue($search,$replace);        if($pic_replcae)&#123;//将图片替换成绝对路径            $image = str_replace(request()-&gt;domain().&#x27;/&#x27;,env(&quot;root_path&quot;),$pic_replcae[&#x27;image&#x27;]);            $tp-&gt;setImageValue($pic_replcae[&#x27;search&#x27;],[&#x27;path&#x27;=&gt;$image,&quot;width&quot; =&gt; 150, &quot;height&quot; =&gt; 150]);        &#125;                if($type == 0)&#123;            //设置保存文件名            $firstName = env(&quot;root_path&quot;).&#x27;public/upload/word/&#x27;;            $alias = $alias ? $alias.&#x27;_&#x27;.time().&quot;.docx&quot; : time().&quot;.docx&quot;;            $firstName = $firstName.$alias;            //保存文档            $tp-&gt;saveAs($firstName);            //生成文件名            $name = pathinfo($firstName,PATHINFO_FILENAME);            //新文件路径            $newUrl = request()-&gt;domain().&quot;/uploads/word/&quot;.$name.&quot;.docx&quot;;            return [&#x27;code&#x27;=&gt;200&#x27;,&#x27;data&#x27;=&gt;[&#x27;url&#x27;=&gt;$newUrl]];        &#125; elseif($type == 1)&#123;            //获取文件名            $name = pathinfo($tmpurl,PATHINFO_FILENAME);            //设置保存文件名            $firstName = env(&quot;root_path&quot;).&#x27;public/upload/word/&#x27;.$name.&quot;.docx&quot;;            //更新保存文档            $tp-&gt;saveAs($firstName);            return [&#x27;code&#x27;=&gt;200&#x27;,&#x27;data&#x27;=&gt;[&#x27;url&#x27;=&gt;$newUrl]];        &#125;    &#125; catch (\Exception $e) &#123;        return [&#x27;code&#x27;=&gt;500,&#x27;msg&#x27;=&gt;$e-&gt;getMessage()];    &#125;&#125;

方法调用实现
//获取模板文档地址$tp_word_url = &quot;项目地址/test.docx&quot;;//变量名（模板设置的变量）$search = [&#x27;name&#x27;,&#x27;email&#x27;];//替换值$replace = [&#x27;heyiki&#x27;,&#x27;1186933877@qq.com&#x27;];$callback = PhpWordLogic::replaceWord($tp_word_url, $search, $replace, 0, &#x27;test&#x27;);图片替换不能与文字替换混在一起，如模板文档的变量值为：img$callback = PhpWordLogic::replaceWord($tp_word_url, $search, $replace, 0, &#x27;test&#x27;, [&#x27;image&#x27;=&gt;&#x27;项目地址/123.png&#x27;,&#x27;search&#x27;=&gt;&#x27;img&#x27;]);

