mysql基础PHP 5 及以上版本建议使用以下方式连接 MySQL :

MySQLi extension (“i” 意为 improved)
PDO (PHP Data Objects)


我是该用 MySQLi ，还是 PDO?
如果你需要一个简短的回答，即 “你习惯哪个就用哪个”。MySQLi 和 PDO 有它们自己的优势：PDO 应用在 12 种不同数据库中， MySQLi 只针对 MySQL 数据库。所以，如果你的项目需要在多种数据库中切换，建议使用 PDO ，这样你只需要修改连接字符串和部分查询语句即可。 使用 MySQLi, 如果不同数据库，你需要重新编写所有代码，包括查询。两者都是面向对象, 但 MySQLi 还提供了 API 接口。两者都支持预处理语句。 预处理语句可以防止 SQL 注入，对于 web 项目的安全性是非常重要的。
连接 MySQL实例 (MySQLi - 面向对象)
&lt;?php$servername = &quot;localhost&quot;;$username = &quot;username&quot;;$password = &quot;password&quot;;// 创建连接$conn = new mysqli($servername, $username, $password);// 检测连接if ($conn-&gt;connect_error) &#123;    die(&quot;连接失败: &quot; . $conn-&gt;connect_error);&#125; echo &quot;连接成功&quot;;?&gt;

实例 (MySQLi - 面向过程)
&lt;?php$servername = &quot;localhost&quot;;$username = &quot;username&quot;;$password = &quot;password&quot;;// 创建连接$conn = mysqli_connect($servername, $username, $password);// 检测连接if (!$conn) &#123;    die(&quot;Connection failed: &quot; . mysqli_connect_error());&#125;echo &quot;连接成功&quot;;?&gt;

实例 (PDO)
&lt;?php$servername = &quot;localhost&quot;;$username = &quot;username&quot;;$password = &quot;password&quot;;try &#123;    $conn = new PDO(&quot;mysql:host=$servername;&quot;, $username, $password);    echo &quot;连接成功&quot;; &#125;catch(PDOException $e)&#123;    echo $e-&gt;getMessage();&#125;?&gt;

关闭连接实例 (MySQLi - 面向对象)
$conn-&gt;close();
实例 (MySQLi - 面向过程)
mysqli_close($conn);
实例 (PDO)
$conn = null;

对数据库进行操作实例 (MySQLi - 面向对象)
&lt;?php$servername = &quot;localhost&quot;;$username = &quot;username&quot;;$password = &quot;password&quot;;$dbname = &quot;myDB&quot;;// 创建连接$conn = new mysqli($servername, $username, $password, $dbname);// 检测连接if ($conn-&gt;connect_error) &#123;    die(&quot;连接失败: &quot; . $conn-&gt;connect_error);&#125; $sql = &quot;INSERT INTO MyGuests (firstname, lastname, email)VALUES (&#x27;John&#x27;, &#x27;Doe&#x27;, &#x27;john@example.com&#x27;)&quot;;if ($conn-&gt;query($sql) === TRUE) &#123;    echo &quot;新记录插入成功&quot;;&#125; else &#123;    echo &quot;Error: &quot; . $sql . &quot;&lt;br&gt;&quot; . $conn-&gt;error;&#125;$conn-&gt;close();?&gt;

实例 (MySQLi - 面向过程)
&lt;?php$servername = &quot;localhost&quot;;$username = &quot;username&quot;;$password = &quot;password&quot;;$dbname = &quot;myDB&quot;;// 创建连接$conn = mysqli_connect($servername, $username, $password, $dbname);// 检测连接if (!$conn) &#123;    die(&quot;Connection failed: &quot; . mysqli_connect_error());&#125;$sql = &quot;INSERT INTO MyGuests (firstname, lastname, email)VALUES (&#x27;John&#x27;, &#x27;Doe&#x27;, &#x27;john@example.com&#x27;)&quot;;if (mysqli_query($conn, $sql)) &#123;    echo &quot;新记录插入成功&quot;;&#125; else &#123;    echo &quot;Error: &quot; . $sql . &quot;&lt;br&gt;&quot; . mysqli_error($conn);&#125;mysqli_close($conn);?&gt;

实例 (PDO)
&lt;?php$servername = &quot;localhost&quot;;$username = &quot;username&quot;;$password = &quot;password&quot;;$dbname = &quot;myDBPDO&quot;;try &#123;    $conn = new PDO(&quot;mysql:host=$servername;dbname=$dbname&quot;, $username, $password);    // 设置 PDO 错误模式，用于抛出异常    $conn-&gt;setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);    $sql = &quot;INSERT INTO MyGuests (firstname, lastname, email)    VALUES (&#x27;John&#x27;, &#x27;Doe&#x27;, &#x27;john@example.com&#x27;)&quot;;    // 使用 exec() ，没有结果返回     $conn-&gt;exec($sql);    echo &quot;新记录插入成功&quot;;&#125;catch(PDOException $e)&#123;    echo $sql . &quot;&lt;br&gt;&quot; . $e-&gt;getMessage();&#125;$conn = null;?&gt;

执行多条sql语句实例 (MySQLi - 面向对象)
&lt;?php$servername = &quot;localhost&quot;;$username = &quot;username&quot;;$password = &quot;password&quot;;$dbname = &quot;myDB&quot;;// 创建链接$conn = new mysqli($servername, $username, $password, $dbname);// 检查链接if ($conn-&gt;connect_error) &#123;    die(&quot;连接失败: &quot; . $conn-&gt;connect_error);&#125; $sql = &quot;INSERT INTO MyGuests (firstname, lastname, email)VALUES (&#x27;John&#x27;, &#x27;Doe&#x27;, &#x27;john@example.com&#x27;);&quot;;$sql .= &quot;INSERT INTO MyGuests (firstname, lastname, email)VALUES (&#x27;Mary&#x27;, &#x27;Moe&#x27;, &#x27;mary@example.com&#x27;);&quot;;$sql .= &quot;INSERT INTO MyGuests (firstname, lastname, email)VALUES (&#x27;Julie&#x27;, &#x27;Dooley&#x27;, &#x27;julie@example.com&#x27;)&quot;;if ($conn-&gt;multi_query($sql) === TRUE) &#123;    echo &quot;新记录插入成功&quot;;&#125; else &#123;    echo &quot;Error: &quot; . $sql . &quot;&lt;br&gt;&quot; . $conn-&gt;error;&#125;$conn-&gt;close();?&gt;

实例 (MySQLi - 面向过程)
&lt;?php$servername = &quot;localhost&quot;;$username = &quot;username&quot;;$password = &quot;password&quot;;$dbname = &quot;myDB&quot;;// 创建链接$conn = mysqli_connect($servername, $username, $password, $dbname);// 检查链接if (!$conn) &#123;    die(&quot;连接失败: &quot; . mysqli_connect_error());&#125;$sql = &quot;INSERT INTO MyGuests (firstname, lastname, email)VALUES (&#x27;John&#x27;, &#x27;Doe&#x27;, &#x27;john@example.com&#x27;);&quot;;$sql .= &quot;INSERT INTO MyGuests (firstname, lastname, email)VALUES (&#x27;Mary&#x27;, &#x27;Moe&#x27;, &#x27;mary@example.com&#x27;);&quot;;$sql .= &quot;INSERT INTO MyGuests (firstname, lastname, email)VALUES (&#x27;Julie&#x27;, &#x27;Dooley&#x27;, &#x27;julie@example.com&#x27;)&quot;;if (mysqli_multi_query($conn, $sql)) &#123;    echo &quot;新记录插入成功&quot;;&#125; else &#123;    echo &quot;Error: &quot; . $sql . &quot;&lt;br&gt;&quot; . mysqli_error($conn);&#125;mysqli_close($conn);?&gt;

实例 (PDO) 事务操作
&lt;?php$servername = &quot;localhost&quot;;$username = &quot;username&quot;;$password = &quot;password&quot;;$dbname = &quot;myDBPDO&quot;;try &#123;    $conn = new PDO(&quot;mysql:host=$servername;dbname=$dbname&quot;, $username, $password);    // set the PDO error mode to exception    $conn-&gt;setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);    // 开始事务    $conn-&gt;beginTransaction();    // SQL 语句    $conn-&gt;exec(&quot;INSERT INTO MyGuests (firstname, lastname, email)     VALUES (&#x27;John&#x27;, &#x27;Doe&#x27;, &#x27;john@example.com&#x27;)&quot;);    $conn-&gt;exec(&quot;INSERT INTO MyGuests (firstname, lastname, email)     VALUES (&#x27;Mary&#x27;, &#x27;Moe&#x27;, &#x27;mary@example.com&#x27;)&quot;);    $conn-&gt;exec(&quot;INSERT INTO MyGuests (firstname, lastname, email)     VALUES (&#x27;Julie&#x27;, &#x27;Dooley&#x27;, &#x27;julie@example.com&#x27;)&quot;);    // 提交事务    $conn-&gt;commit();    echo &quot;新记录插入成功&quot;;&#125;catch(PDOException $e)&#123;    // 如果执行失败回滚    $conn-&gt;rollback();    echo $sql . &quot;&lt;br&gt;&quot; . $e-&gt;getMessage();&#125;$conn = null;?&gt;

数据查询实例 (MySQLi - 面向对象)
&lt;?php$servername = &quot;localhost&quot;;$username = &quot;username&quot;;$password = &quot;password&quot;;$dbname = &quot;myDB&quot;;// 创建连接$conn = new mysqli($servername, $username, $password, $dbname);// Check connectionif ($conn-&gt;connect_error) &#123;    die(&quot;连接失败: &quot; . $conn-&gt;connect_error);&#125; $sql = &quot;SELECT id, firstname, lastname FROM MyGuests&quot;;$result = $conn-&gt;query($sql);if ($result-&gt;num_rows &gt; 0) &#123;    // 输出数据    while($row = $result-&gt;fetch_assoc()) &#123;        echo &quot;id: &quot; . $row[&quot;id&quot;]. &quot; - Name: &quot; . $row[&quot;firstname&quot;]. &quot; &quot; . $row[&quot;lastname&quot;]. &quot;&lt;br&gt;&quot;;    &#125;&#125; else &#123;    echo &quot;0 结果&quot;;&#125;$conn-&gt;close();?&gt;

实例 (MySQLi - 面向过程)
&lt;?php$servername = &quot;localhost&quot;;$username = &quot;username&quot;;$password = &quot;password&quot;;$dbname = &quot;myDB&quot;;// 创建连接$conn = mysqli_connect($servername, $username, $password, $dbname);// Check connectionif (!$conn) &#123;    die(&quot;连接失败: &quot; . mysqli_connect_error());&#125;$sql = &quot;SELECT id, firstname, lastname FROM MyGuests&quot;;$result = mysqli_query($conn, $sql);if (mysqli_num_rows($result) &gt; 0) &#123;    // 输出数据    while($row = mysqli_fetch_assoc($result)) &#123;        echo &quot;id: &quot; . $row[&quot;id&quot;]. &quot; - Name: &quot; . $row[&quot;firstname&quot;]. &quot; &quot; . $row[&quot;lastname&quot;]. &quot;&lt;br&gt;&quot;;    &#125;&#125; else &#123;    echo &quot;0 结果&quot;;&#125;mysqli_close($conn);?&gt;

